import{_ as t,a as n,b as o}from"./chunks/15c-ai-agents-mobile.CW_dMZjn.js";import{_ as s,o as a,c as r,a3 as i}from"./chunks/framework.BGhsAJMQ.js";const b=JSON.parse('{"title":"AI Agents","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai-agents.md","filePath":"features/ai-agents.md","lastUpdated":1793949581000}'),d={name:"features/ai-agents.md"};function l(p,e,c,g,u,h){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ai-agents" tabindex="-1">AI Agents <a class="header-anchor" href="#ai-agents" aria-label="Permalink to &quot;AI Agents&quot;">​</a></h1><p>Use <strong>AI Agents</strong> on the selected Filebox Agent to list coding-agent windows, read output, send prompts and answer with allowlisted keys. This is a separate backend integration, not a remote shell or a read-only preview.</p><p><img src="'+t+'" alt="AI Agents list and detail on desktop"></p><h2 id="enable-and-set-up" tabindex="-1">Enable and set up <a class="header-anchor" href="#enable-and-set-up" aria-label="Permalink to &quot;Enable and set up&quot;">​</a></h2><p>In <strong>Settings</strong> (Agent Settings), turn on <strong>AI Agents</strong> and choose its backend. The switch is saved on that Agent and shared across browsers. Turning it off stops Filebox controls and monitoring, not the backend or running coding agents.</p><ul><li><strong>Herdr</strong>: install the <a href="https://herdr.ink" target="_blank" rel="noreferrer">Herdr CLI</a> on the Agent machine (checked against v0.9.5). Put <code>herdr</code> on the Agent process&#39;s PATH or set <code>FILEBOX_AGENT_HERDR</code> to its executable, then use <strong>Check installation</strong>.</li><li><strong>hc (experimental)</strong>: connects local live herdr-core terminals opted in with <code>fb=&lt;name&gt;</code> or <code>filebox=&lt;name&gt;</code> labels. See <a href="/filebox/ops/agent#experimental-hc-backend">experimental hc setup</a>. Automatic selection prefers Herdr when both are installed.</li></ul><p><strong>Meet AI Agents</strong> introduces the integration; <strong>Set up AI Agents</strong> explains missing installation or disabled settings. <strong>AI agent backend is not running</strong> means the CLI was found but the backend needs to be started on the Agent machine.</p><p>At Agent startup, <code>FILEBOX_AGENT_AI_AGENTS_ENABLED=0</code> / <code>1</code> overrides and locks the switch. <code>FILEBOX_AGENT_AI_AGENTS_BACKEND</code> locks backend selection. Remove the relevant variable and restart the Agent to restore web control.</p><p><img src="'+n+'" alt="Agent Settings AI Agents section"></p><h2 id="windows-output-and-input" tabindex="-1">Windows, output and input <a class="header-anchor" href="#windows-output-and-input" aria-label="Permalink to &quot;Windows, output and input&quot;">​</a></h2><ul><li>Search windows by name, agent kind, working directory or pane ID; filter by status when the backend supports status detection. <strong>Draft</strong> marks unsent input. Each window keeps its own draft while the view is mounted; rejected prompts retain it.</li><li>Select a window to read its output. <strong>Refresh output</strong> gets a fresh snapshot; AI Agents settings controls automatic output refresh. Refresh does not scroll the remote application&#39;s transcript.</li><li>Send a prompt from the composer. Enter adds a line; Ctrl / ⌘ + Enter sends. Inspect output before retrying an interrupted send: cancelling a wait cannot retract accepted input.</li><li>Use Enter, Esc and Up/Down, or open <strong>Keys</strong> for searchable pi, Claude Code and Codex shortcut profiles. Detection picks a profile; you can correct it. Opening Keys or changing profiles sends nothing. Shortcuts use a bounded allowlist, not arbitrary raw input; upstream support and custom keybindings can differ.</li><li>Needs-input reminders require an open Filebox page. Detection can miss questions; reminders are not a guarantee of notification when the page is closed.</li></ul><p><img src="'+o+'" alt="AI Agents on mobile"></p><h2 id="prompt-review" tabindex="-1">Prompt review <a class="header-anchor" href="#prompt-review" aria-label="Permalink to &quot;Prompt review&quot;">​</a></h2><p>By default, every prompt is reviewed at the Hub before delivery. Destructive commands, permanent deletion and secret extraction are blocked; normal data analysis and development are allowed. The reviewer sees your prompt and the window&#39;s recent output.</p><p>The view shows review <strong>on with its model</strong>, <strong>off</strong>, or <strong>not configured</strong> (prompts disabled). Missing configuration or a failed review refuses delivery rather than bypassing review. Reads, status and allowlisted keys remain available; keys are not LLM-reviewed. Coding agents can modify files outside browse roots, so use their controls with care.</p><p>An administrator configures review only on the Hub, not in the browser. See <a href="/filebox/ops/hub#prompt-review-ai-agents">Prompt review (AI Agents)</a>.</p>',16)])])}const f=s(d,[["render",l]]);export{b as __pageData,f as default};
